import { DiagramNode, DiagramEdge } from '../types';

/**
 * Generates DBML (Database Markup Language) compliant with dbdiagram.io specification.
 * https://dbdiagram.io/docs
 */
export function generateDBML(nodes: DiagramNode[], edges: DiagramEdge[]): string {
  const lines: string[] = [
    '// Generated by VetroLog Database Visualizer',
    `// Created at: ${new Date().toISOString()}`,
    '',
  ];

  nodes.forEach((node) => {
    lines.push(`Table ${node.name} {`);
    node.columns.forEach((col) => {
      const type = (col.type || 'text').toLowerCase();
      const settings: string[] = [];
      if (col.isPrimaryKey) settings.push('pk');
      if (!col.isNullable && !col.isPrimaryKey) settings.push('not null');
      if (col.defaultValue) settings.push(`default: \`${col.defaultValue}\``);

      const settingsStr = settings.length > 0 ? ` [${settings.join(', ')}]` : '';
      lines.push(`  ${col.name} ${type}${settingsStr}`);
    });
    lines.push('}');
    lines.push('');
  });

  // Relationships (Refs)
  if (edges.length > 0) {
    lines.push('// Relationships');
    edges.forEach((edge) => {
      const isInf = edge.isInferred ? ' // (inferred)' : '';
      lines.push(
        `Ref: ${edge.sourceTable}.${edge.sourceColumn} > ${edge.targetTable}.${edge.targetColumn}${isInf}`
      );
    });
    lines.push('');
  }

  return lines.join('\n');
}

/**
 * Generates standard Mermaid ER Diagram format
 */
export function generateMermaid(nodes: DiagramNode[], edges: DiagramEdge[]): string {
  const lines: string[] = ['erDiagram'];

  // Relationships
  edges.forEach((edge) => {
    const src = edge.sourceTable.replace(/[^a-zA-Z0-9_]/g, '_');
    const tgt = edge.targetTable.replace(/[^a-zA-Z0-9_]/g, '_');
    lines.push(`  ${tgt} ||--o{ ${src} : "${edge.sourceColumn}"`);
  });

  // Tables & Columns
  nodes.forEach((node) => {
    const tbl = node.name.replace(/[^a-zA-Z0-9_]/g, '_');
    lines.push(`  ${tbl} {`);
    node.columns.forEach((col) => {
      const type = (col.type || 'string').replace(/[^a-zA-Z0-9_]/g, '');
      const pk = col.isPrimaryKey ? ' PK' : '';
      lines.push(`    ${type} ${col.name}${pk}`);
    });
    lines.push('  }');
  });

  return lines.join('\n');
}

/**
 * Generates SQL DDL representation
 */
export function generateSQL(nodes: DiagramNode[], edges: DiagramEdge[]): string {
  const lines: string[] = [
    '-- Generated DDL Schema Map by VetroLog Studio',
    '',
  ];

  nodes.forEach((node) => {
    lines.push(`CREATE TABLE "${node.name}" (`);
    const colDefs = node.columns.map((col) => {
      const pk = col.isPrimaryKey ? ' PRIMARY KEY' : '';
      const notNull = !col.isNullable && !col.isPrimaryKey ? ' NOT NULL' : '';
      const def = col.defaultValue ? ` DEFAULT ${col.defaultValue}` : '';
      return `  "${col.name}" ${col.type || 'TEXT'}${pk}${notNull}${def}`;
    });
    lines.push(colDefs.join(',\n'));
    lines.push(');');
    lines.push('');
  });

  if (edges.length > 0) {
    lines.push('-- Foreign Key Constraints');
    edges.forEach((edge) => {
      const cName = edge.constraintName || `fk_${edge.sourceTable}_${edge.sourceColumn}`;
      lines.push(
        `ALTER TABLE "${edge.sourceTable}" ADD CONSTRAINT "${cName}" FOREIGN KEY ("${edge.sourceColumn}") REFERENCES "${edge.targetTable}" ("${edge.targetColumn}");`
      );
    });
    lines.push('');
  }

  return lines.join('\n');
}

